# Part C · Section 13 — troponin, CK-MB, BNP and NT-proBNP: physiology, timing, and what moves them without heart disease
def hdr(*cols):
    return ('<table style="border-collapse:collapse;margin:8px 0;font-size:.95em"><tr>' +
            ''.join(f'<th style="border:1px solid #bbb;padding:4px 10px;text-align:left">{c}</th>' for c in cols) + '</tr>')
def row(*cells):
    return '<tr>' + ''.join(f'<td style="border:1px solid #bbb;padding:4px 10px">{c}</td>' for c in cells) + '</tr>'

